18	// V2: Brand views and disconnects their connected affiliates. Single-brand constraint means each affiliate has exactly one brand.
19	class BrandAffiliateController extends ApiController
20	{
21	    use ResolveCurrentProfessional;
22	
23	    public function index(Request $request): JsonResponse
24	    {
25	        $professional = $this->currentProfessional($request);
26	
27	        if (mb_strtolower(trim((string) $professional->professional_type)) !== 'brand') {
28	            return $this->error('Only brand accounts can view affiliates.', 403);
29	        }
30	
31	        $brandId = $professional->id;
32	
33	        $links = BrandPartnerLink::query()
34	            ->where('brand_professional_id', $brandId)
35	            ->orderByDesc('updated_at')
36	            ->get(['affiliate_professional_id', 'slot', 'custom_photos_enabled', 'updated_at']);
37	
38	        $affiliateIds = $links
39	            ->pluck('affiliate_professional_id')
40	            ->unique()
41	            ->values()
42	            ->all();
43	
44	        $sitesByProfessionalId = Site::query()
45	            ->with(['professional'])
46	            ->whereIn('professional_id', $affiliateIds)
47	            ->whereHas('professional', function ($query): void {
48	                $query
49	                    ->where('status', 'active')
50	                    ->where('professional_type', '!=', 'brand');
51	            })
52	            ->get()
53	            ->keyBy('professional_id');
54	
55	        $affiliates = $links
56	            ->map(function (BrandPartnerLink $link) use ($sitesByProfessionalId): ?array {
57	                /** @var Site|null $site */
58	                $site = $sitesByProfessionalId->get($link->affiliate_professional_id);
59	                if (! $site) {
60	                    return null;
61	                }
62	
63	                $connectedProfessional = $site->professional;
64	                $name = trim(implode(' ', array_filter([
65	                    $connectedProfessional?->first_name,
66	                    $connectedProfessional?->last_name,
67	                ])));
68	
69	                return [
70	                    'id' => $connectedProfessional?->id,
71	                    'full_name' => $name !== '' ? $name : ($connectedProfessional?->display_name ?? $connectedProfessional?->handle ?? 'Unknown'),
72	                    'display_name' => $connectedProfessional?->display_name,
73	                    'handle' => $connectedProfessional?->handle,
74	                    'professional_type' => $connectedProfessional?->professional_type,
75	                    'email' => $connectedProfessional?->primary_email ?? $connectedProfessional?->public_contact_email,
76	                    'phone' => $connectedProfessional?->phone ?? $connectedProfessional?->public_contact_number,
77	                    'connected_at' => optional($link->updated_at)->toIso8601String(),
78	                    'is_primary' => (int) $link->slot === BrandPartnerLinkService::PRIMARY_SLOT,
79	                    'custom_photos_enabled' => $link->custom_photos_enabled,
80	                ];
81	            })
82	            ->filter(fn (?array $affiliate): bool => is_array($affiliate) && filled($affiliate['id']))
83	            ->values()
84	            ->all();
85	
86	        return $this->success([
87	            'affiliates' => $affiliates,
88	        ]);
89	    }
