91	    public function disconnect(
92	        Request $request,
93	        string $affiliateId,
94	        BrandPartnerLinkLifecycleService $lifecycle,
95	    ): JsonResponse {
96	        $professional = $this->currentProfessional($request);
97	
98	        if (mb_strtolower(trim((string) $professional->professional_type)) !== 'brand') {
99	            return $this->error('Only brand accounts can disconnect affiliates.', 403);
100	        }
101	
102	        $data = $request->validate([
103	            'reason' => ['nullable', 'string', 'max:500'],
104	        ]);
105	
106	        $affiliate = Professional::query()->whereKey($affiliateId)->first();
