7	
8	// V2: Abstract base controller. Provides success(), error(), and paginated() response helpers for all API endpoints.
9	abstract class ApiController extends Controller
10	{
11	    /**
12	     * Return a success JSON response.
13	     *
14	     * Signature: success($data, $status) — no message argument.
15	     * Common footgun: success($data, 'message', 200) passes 'message' as $status
16	     * and silently drops 200. Pass only data + integer status code.
17	     */
18	    protected function success($data = null, int $status = 200): JsonResponse
19	    {
20	        return response()->json($data, $status);
21	    }
22	
23	    /**
24	     * Return error response with message.
25	     */
26	    protected function error(string $message, int $status = 400, array $errors = []): JsonResponse
27	    {
28	        $response = ['message' => $message];
29	
30	        if (! empty($errors)) {
31	            $response['errors'] = $errors;
32	        }
33	
34	        return response()->json($response, $status);
35	    }
36	
37	    /**
38	     * Return paginated response.
39	     */
40	    protected function paginated($paginator, string $dataKey = 'data'): JsonResponse
41	    {
42	        return response()->json([
43	            $dataKey => $paginator->items(),
44	            'meta' => [
45	                'current_page' => $paginator->currentPage(),
46	                'per_page' => $paginator->perPage(),
47	                'total' => $paginator->total(),
48	                'last_page' => $paginator->lastPage(),
49	                'next_page_url' => $paginator->nextPageUrl(),
50	                'prev_page_url' => $paginator->previousPageUrl(),
51	            ],
52	        ]);
53	    }
54	}
