275	    /**
276	     * Check whether the storefront is reachable at its base URL.
277	     *
278	     * Makes a lightweight GET with redirects disabled so we can
279	     * distinguish "Hydrogen is serving" (2xx) from "Shopify is
280	     * falling through to the primary domain" (3xx redirect).
281	     *
282	     * @return 'live'|'redirecting'|'unreachable'
283	     */
284	    private function checkStorefrontStatus(BrandStoreSettings $settings, string $subdomain): string
285	    {
286	        $url = $settings->storefrontBaseUrl($subdomain);
287	
288	        try {
289	            $response = Http::withOptions([
290	                'allow_redirects' => false,
291	                'timeout' => 5,
292	                'connect_timeout' => 3,
293	            ])->get($url);
294	
295	            if ($response->successful()) {
296	                return 'live';
297	            }
298	
299	            if ($response->redirect()) {
300	                return 'redirecting';
301	            }
302	
303	            return 'unreachable';
304	        } catch (\Throwable) {
305	            return 'unreachable';
306	        }
307	    }
