132	    /**
133	     * PATCH /brand/catalog/{productGid}/metafields
134	     *
135	     * Bulk update any combination of sidest.* metafields on one product in a single
136	     * Shopify GraphQL call. All fields are optional — only the keys present in the
137	     * request are touched. Sending null (or [] for arrays) deletes the metafield,
138	     * which restores the dynamic default for that setting.
139	     *
140	     * Full conceptual model + scenario table: docs/brand-catalog-v2.md
141	     */
142	    public function updateMetafields(UpdateProductMetafieldsRequest $request, string $productGid): JsonResponse
143	    {
144	        $pro = $this->currentProfessional($request);
145	
146	        if (! $this->isValidProductGid($productGid)) {
147	            return $this->error('Invalid product GID format.', 422);
148	        }
149	
150	        try {
151	            $resolved = $this->catalogService->resolveBrandIntegration($pro);
152	        } catch (\RuntimeException $e) {
153	            return $this->error($e->getMessage(), $e->getCode() ?: 500);
154	        }
155	
156	        $integration = $resolved['integration'];
157	        $validated = $request->validated();
158	        $metafieldsToSet = [];
159	
160	        // Whether this call is (re-)activating the product. When true, after
161	        // the sidest.active write lands we also clear every variant's
162	        // explicit sidest.enabled=false metafield so re-activation puts
163	        // variants back to the default-enabled state.
164	        $activatingProduct = false;
165	        if (array_key_exists('active', $validated)) {
166	            $metafieldsToSet[] = ['key' => 'active', 'value' => $validated['active'] ? 'true' : 'false', 'type' => 'boolean'];
167	            $activatingProduct = (bool) $validated['active'];
168	        }
169	
170	        if (array_key_exists('commission_override', $validated)) {
171	            if ($validated['commission_override'] === null) {
172	                try {
173	                    $this->catalogService->deleteProductMetafield($integration, $productGid, 'commission_override');
174	                } catch (\Throwable $e) {
175	                    return $this->error('Unable to reach Shopify. Please try again.', 502);
176	                }
177	            } else {
178	                $metafieldsToSet[] = ['key' => 'commission_override', 'value' => (string) $validated['commission_override'], 'type' => 'number_decimal'];
179	            }
180	        }
181	
182	        if (array_key_exists('affiliate_discount_pct', $validated)) {
183	            if ($validated['affiliate_discount_pct'] === null) {
184	                try {
185	                    $this->catalogService->deleteProductMetafield($integration, $productGid, 'affiliate_discount_pct');
186	                } catch (\Throwable $e) {
187	                    return $this->error('Unable to reach Shopify. Please try again.', 502);
188	                }
189	            } else {
190	                $metafieldsToSet[] = ['key' => 'affiliate_discount_pct', 'value' => (string) $validated['affiliate_discount_pct'], 'type' => 'number_decimal'];
191	            }
192	        }
193	
194	        if (array_key_exists('custom_photos_enabled', $validated)) {
195	            if ($validated['custom_photos_enabled'] === null) {
196	                try {
197	                    $this->catalogService->deleteProductMetafield($integration, $productGid, 'custom_photos_enabled');
198	                } catch (\Throwable $e) {
199	                    return $this->error('Unable to reach Shopify. Please try again.', 502);
200	                }
201	            } else {
202	                $metafieldsToSet[] = ['key' => 'custom_photos_enabled', 'value' => $validated['custom_photos_enabled'] ? 'true' : 'false', 'type' => 'boolean'];
203	            }
204	        }
205	
206	        // Variant gating: brands disable specific variants via per-variant sidest.enabled
207	        // metafields (ownerType: PRODUCTVARIANT). Missing metafield = enabled (dynamic
208	        // default — new variants auto-appear). Only variants explicitly set to false are
209	        // hidden from affiliates and Hydrogen. Hydrogen reads this directly from the
210	        // Storefront API (PUBLIC_READ), no Laravel intermediary needed.
211	        if (array_key_exists('disabled_variant_gids', $validated)) {
212	            $submitted = $validated['disabled_variant_gids'];
213	
214	            try {
215	                $productVariantGids = $this->catalogService->fetchProductVariantGids($integration, $productGid);
216	            } catch (\Throwable $e) {
217	                return $this->error('Unable to reach Shopify. Please try again.', 502);
218	            }
219	
220	            if ($submitted !== null && $submitted !== []) {
221	                if (empty($productVariantGids)) {
222	                    return $this->error('Product has no variants to restrict.', 422);
223	                }
224	
225	                $allowed = array_flip($productVariantGids);
226	                $invalid = array_values(array_filter($submitted, fn (string $gid) => ! isset($allowed[$gid])));
227	
228	                if (! empty($invalid)) {
229	                    return $this->error('One or more variant GIDs do not belong to this product.', 422);
230	                }
231	            }
232	
233	            try {
234	                $result = $this->catalogService->setVariantEnabledStates(
235	                    $integration,
236	                    $productGid,
237	                    $productVariantGids,
238	                    $submitted ?? []
239	                );
240	
241	                if (! $result['success']) {
242	                    $msg = $result['userErrors'][0]['message'] ?? 'Failed to update variant states.';
243	
244	                    return $this->error($msg, 422);
245	                }
246	            } catch (\Throwable $e) {
247	                return $this->error('Unable to reach Shopify. Please try again.', 502);
248	            }
249	        }
250	
251	        if (! empty($metafieldsToSet)) {
252	            try {
253	                $result = $this->catalogService->setProductMetafields($integration, $productGid, $metafieldsToSet);
254	
255	                if (! $result['success']) {
256	                    $msg = $result['userErrors'][0]['message'] ?? 'Failed to update metafields.';
257	
258	                    return $this->error($msg, 422);
259	                }
260	            } catch (\RuntimeException $e) {
261	                return $this->error($e->getMessage(), $e->getCode() ?: 502);
262	            } catch (\Throwable $e) {
263	                return $this->error('Unable to reach Shopify. Please try again.', 502);
264	            }
265	        }
266	
267	        // Activation cascade: when the product is being set active, sweep away
268	        // any lingering `sidest.enabled=false` variant metafields so the
269	        // brand's expectation — "making the product available re-enables all
270	        // its variants" — actually happens in Shopify data, not just the UI.
271	        //
272	        // Best-effort: a failure here logs but doesn't fail the main update
273	        // (the product is still active; brands can manually flip variants
274	        // if the sweep had partial errors).
275	        if ($activatingProduct) {
276	            try {
277	                $this->catalogService->clearVariantDisablesForProduct($integration, $productGid);
278	            } catch (\Throwable $e) {
279	                \Log::warning('Failed to cascade variant enable on product activation', [
280	                    'product_gid' => $productGid,
281	                    'error' => $e->getMessage(),
282	                ]);
283	            }
284	        }
285	
286	        return $this->success(['updated' => true]);
287	    }
