222	    public function reorder(Request $request, string $gid): JsonResponse
223	    {
224	        $pro = $this->currentProfessional($request);
225	
226	        if (! preg_match(self::GID_PATTERN, $gid)) {
227	            return $this->error('Invalid product ID.', 422);
228	        }
229	
230	        // Verify the GID is in the affiliate's selections to prevent IDOR reorders
231	        $hasSelection = AffiliateProductSelection::query()
232	            ->where('affiliate_professional_id', $pro->id)
233	            ->where('shopify_product_gid', $gid)
234	            ->exists();
235	
236	        if (! $hasSelection) {
237	            return $this->error('Product not found in your selections.', 404);
238	        }
239	
240	        $request->validate([
241	            'ids' => ['required', 'array', 'min:1'],
242	            'ids.*' => ['required', 'uuid'],
243	        ]);
244	
245	        $pro->loadMissing('site');
246	        $site = $this->currentSite($pro);
247	        $ids = array_values(array_unique($request->validated('ids')));
248	
249	        DB::transaction(function () use ($site, $gid, $ids) {
250	            if (DB::getDriverName() === 'pgsql') {
251	                DB::select('select pg_advisory_xact_lock(hashtext(?))', ["site-product-photos:{$site->id}:{$gid}"]);
252	            }
253	
254	            $images = SiteMedia::query()
255	                ->where('site_id', $site->id)
256	                ->where('pool', self::POOL)
257	                ->where('product_gid', $gid)
258	                ->where('is_active', true)
259	                ->lockForUpdate()
260	                ->orderBy('sort_order')
261	                ->get(['id', 'sort_order']);
262	
263	            if ($images->isEmpty()) {
264	                abort(422, 'No custom photos found for this product.');
265	            }
266	
267	            $ownedIds = $images->pluck('id')->flip();
268	            foreach ($ids as $id) {
269	                if (! isset($ownedIds[$id])) {
270	                    abort(422, 'One or more product photos are invalid.');
271	                }
272	            }
273	
274	            $remaining = array_values(array_diff($images->pluck('id')->all(), $ids));
275	            $ordered = array_merge($ids, $remaining);
276	
277	            $offset = $images->count() + 1000;
278	            foreach ($ordered as $index => $id) {
279	                SiteMedia::where('site_id', $site->id)->where('id', $id)
280	                    ->update(['sort_order' => $offset + $index]);
281	            }
282	            foreach ($ordered as $index => $id) {
283	                SiteMedia::where('site_id', $site->id)->where('id', $id)
284	                    ->update(['sort_order' => $index]);
285	            }
286	        });
287	
288	        app(SiteCacheService::class)->invalidateSite($site);
289	
290	        return $this->success(['ok' => true]);
291	    }
