293	    private function dispatchImageJob(string $imageId, string $originalPath, string $basePath): void
294	    {
295	        $processInline = in_array(app()->environment(), ['local', 'testing'], true)
296	            || config('queue.default', 'sync') === 'sync';
297	
298	        try {
299	            if ($processInline) {
300	                ProcessImageVariantsJob::dispatchSync(
301	                    originalPath: $originalPath,
302	                    imageId: $imageId,
303	                    basePath: $basePath,
304	                );
305	            } else {
306	                ProcessImageVariantsJob::dispatch(
307	                    originalPath: $originalPath,
308	                    imageId: $imageId,
309	                    basePath: $basePath,
310	                );
311	            }
312	        } catch (Throwable $e) {
313	            Log::error('Product photo: image processing dispatch failed', [
314	                'image_id' => $imageId,
315	                'error' => $e->getMessage(),
316	            ]);
317	        }
318	    }
