203	    public function cartEvent(CartEventRequest $request): JsonResponse
204	    {
205	        $data = $request->validated();
206	
207	        $site = $this->resolveSiteFromData($data);
208	
209	        if (! $site) {
210	            $statusCode = ! empty($data['site_id']) ? 422 : 404;
211	
212	            return $this->error('Site not found', $statusCode);
213	        }
214	
215	        if (! $site->is_published) {
216	            return $this->error('Site not published', 403);
217	        }
218	
219	        $event = new CartEvent([
220	            'event_type' => $data['event_type'],
221	            'occurred_at' => now(),
222	            'session_id' => $data['session_id'] ?? null,
223	            'visitor_id' => $data['visitor_id'] ?? null,
224	            'ip_hash' => $this->hashIp($request->ip()),
225	            'shopify_product_id' => $data['shopify_product_id'] ?? null,
226	            'quantity' => $data['quantity'] ?? null,
227	        ]);
228	        $event->professional_id = $site->professional_id;
229	        $event->site_id = $site->id;
230	        $event->save();
231	
232	        try {
233	            $this->analyticsCache->invalidateAnalytics($site->professional_id);
234	        } catch (Throwable) {
235	        }
236	
237	        return $this->success(['message' => 'Cart event recorded', 'event_id' => $event->id], 201);
238	    }
