28	// V2: Account signup/update. Creates professional + site, applies type defaults, handles affiliate invite claims and brand partner connections. Entry point for affiliate/professional signup.
29	class BootstrapController extends ApiController
30	{
31	    public function __construct(
32	        private readonly SiteProvisioningService $siteProvisioning,
33	    ) {}
34	
35	    public function bootstrap(
36	        BootstrapRequest $request,
37	        BrandAffiliateInviteService $brandAffiliateInviteService,
38	        BrandPartnerLinkService $brandPartnerLinks,
39	        AccountTypeDefaultsService $accountTypeDefaultsService
40	    ) {
41	        $uid = $request->attributes->get('supabase_uid');
42	        if (! is_string($uid) || $uid === '') {
43	            return $this->error('Unauthenticated', 401);
44	        }
45	
46	        if ($this->isWaitlistModeEnabled() && ! $this->hasExistingProfessional($uid)) {
47	            return $this->error(
48	                'New account creation is currently waitlist-only. Please join the waitlist.',
49	                403,
50	                ['code' => 'WAITLIST_ONLY']
51	            );
52	        }
53	
54	        $data = $request->validated();
55	
56	        try {
57	            $allowedProfessionalTypes = array_keys(config('sidest.professional_types', []));
58	            $resolveProfessionalType = static function (mixed $candidate) use ($allowedProfessionalTypes): string {
59	                if (is_string($candidate)) {
60	                    $normalized = mb_strtolower(trim($candidate));
61	                    if ($normalized !== '' && in_array($normalized, $allowedProfessionalTypes, true)) {
62	                        return $normalized;
63	                    }
64	                }
65	
66	                return 'professional';
67	            };
68	
69	            $result = DB::transaction(function () use ($uid, $data, $brandAffiliateInviteService, $brandPartnerLinks, $accountTypeDefaultsService, $resolveProfessionalType) {
70	                $createdProfessional = false;
71	
72	                $professional = Professional::query()->where('auth_user_id', $uid)->first();
73	
74	                if (! $professional) {
75	                    $createdProfessional = true;
76	                    $professional = new Professional([
77	                        'handle' => $data['handle'],
78	                        'display_name' => $data['display_name'],
79	                        'bio' => null,
80	                        'country_code' => $data['country_code'] ?? null,
81	                        'timezone' => $data['timezone'] ?? null,
82	                        'professional_type' => $resolveProfessionalType($data['professional_type'] ?? null),
83	                        'status' => 'active',
84	                        'onboarding_step' => 0,
85	                        'qr_slug' => $this->siteProvisioning->generateQrSlug($data['handle'] ?? null),
86	                        'phone' => $data['phone'] ?? null,
87	                        'primary_email' => $data['primary_email'],
88	                        'first_name' => $data['first_name'] ?? '',
89	                        'last_name' => $data['last_name'] ?? null,
90	
91	                        'public_contact_number' => null,
92	                        'public_contact_email' => null,
93	                        'handle_lc' => $data['handle_lc'],
94	                    ]);
95	                    $professional->auth_user_id = $uid;
96	                } else {
97	
98	                    if (in_array($professional->status, ['disabled', 'suspended', 'pending_deletion'], true)) {
99	                        return $this->error('Account is disabled. Contact support.', 403);
100	                    }
101	
102	                    $fill = [
103	                        'handle' => $data['handle'],
104	                        'display_name' => $data['display_name'],
105	                        'primary_email' => $data['primary_email'],
106	                        'phone' => $data['phone'] ?? $professional->phone,
107	                        'first_name' => $data['first_name'] ?? $professional->first_name,
108	                        'last_name' => $data['last_name'] ?? $professional->last_name,
109	                        'country_code' => $data['country_code'] ?? $professional->country_code,
110	                        'timezone' => $data['timezone'] ?? $professional->timezone,
111	                        'professional_type' => $resolveProfessionalType($data['professional_type'] ?? $professional->professional_type),
112	                        'handle_lc' => $data['handle_lc'],
113	                    ];
114	
115	                    if (array_key_exists('phone', $data)) {
116	                        $fill['phone'] = $data['phone'];
117	                    }
118	
119	                    $professional->fill($fill);
120	                }
121	                if (! is_string($professional->qr_slug) || $professional->qr_slug === '') {
122	                    $professional->qr_slug = $this->siteProvisioning->generateQrSlug($professional->handle ?? null);
123	                }
124	                $professional->save();
125	
126	                // Add to Side St updates list once (global list). Do NOT overwrite if they already unsubscribed.
127	                $this->ensureSidestUpdatesSubscription($professional->primary_email);
128	
129	                $site = Site::query()->where('professional_id', $professional->id)->first();
130	
131	                if (! $site) {
132	                    $base = $this->siteProvisioning->subdomainBaseFromHandle($data['handle']);
133	
134	                    $site = $this->siteProvisioning->createSiteWithRetry($professional->id, $base);
135	                }
136	
137	                // Apply account-type defaults for new professionals
138	                if ($createdProfessional) {
139	                    $accountTypeDefaultsService->applyDefaults($professional, $site);
140	
141	                    if ($professional->professional_type === 'brand') {
142	                        BrandProfile::firstOrCreate(
143	                            ['professional_id' => (string) $professional->id],
144	                            ['setup_complete' => false]
145	                        );
146	                    }
147	                }
148	
149	                if (is_string($data['invite_token'] ?? null) && trim((string) $data['invite_token']) !== '') {
150	                    $invite = $brandAffiliateInviteService->findByToken((string) $data['invite_token']);
151	                    if (! $invite) {
152	                        throw new RuntimeException('Invite not found.');
153	                    }
154	
155	                    $brandAffiliateInviteService->claimInvite($invite, $professional);
156	                    $this->syncSiteBrandPartnerSettings($site, $brandPartnerLinks, (string) $professional->id);
157	                    $accountTypeDefaultsService->applyAffiliateDefaults($professional, $site, (string) $invite->brand_professional_id);
158	                } elseif (is_string($data['brand_partner_professional_id'] ?? null) && trim((string) $data['brand_partner_professional_id']) !== '') {
159	                    $brandPartnerProfessional = Professional::query()
160	                        ->whereKey((string) $data['brand_partner_professional_id'])
161	                        ->where('professional_type', 'brand')
162	                        ->first();
163	
164	                    if (! $brandPartnerProfessional) {
165	                        throw new RuntimeException('Brand partner not found.');
166	                    }
167	
168	                    $affiliateId = (string) $professional->id;
169	                    $brandId = (string) $brandPartnerProfessional->id;
