178	                } elseif (is_string($data['join_brand_handle'] ?? null) && trim((string) $data['join_brand_handle']) !== '') {
179	                    $joinBrand = Professional::query()
180	                        ->where('handle_lc', strtolower(trim((string) $data['join_brand_handle'])))
181	                        ->where('professional_type', 'brand')
