196	                            }
197	                        }
198	                    }
199	                }
200	
201	                // Shopify setup token: create integration from cached OAuth credentials
202	                $shopifyIntegrationId = null;
203	                $shopifySetupToken = is_string($data['shopify_setup_token'] ?? null) ? trim((string) $data['shopify_setup_token']) : '';
204	                if ($shopifySetupToken !== '') {
205	                    // Peek first — consume only after transaction succeeds (prevents token loss on rollback)
206	                    $shopifyData = app(ShopifySetupTokenService::class)->peek($shopifySetupToken);
