213	                    $shopCurrency = strtoupper(trim((string) Arr::get($shopifyData['shop_data'], 'currency', '')));
214	
215	                    $integration = ProfessionalIntegration::create([
216	                        'professional_id' => (string) $professional->id,
217	                        'provider' => ProfessionalIntegration::PROVIDER_SHOPIFY,
218	                        'external_account_id' => $shopDomain,
219	                        'access_token' => $shopifyData['access_token'],
220	                        'provider_metadata' => [
221	                            'shop_domain' => $shopDomain,
222	                            'shop_id' => $shopId !== '' ? "gid://shopify/Shop/{$shopId}" : null,
223	                            'shop_currency' => $shopCurrency !== '' ? $shopCurrency : null,
224	                            'scopes' => $shopifyData['scopes'],
225	                            'webhook_orders_topic' => config('services.shopify.webhook_orders_topic', 'orders/paid'),
226	                            'connected_at' => now()->toIso8601String(),
227	                            'webhook_registration_state' => 'queued',
228	                        ],
229	                    ]);
230	
231	                    $shopifyIntegrationId = (string) $integration->id;
232	
233	                    // Auto-fill profile from Shopify shop data (address, phone, etc. — not email)
234	                    $brandProfile = BrandProfile::where('professional_id', $professional->id)->first();
235	                    app(ShopProfileAutoFillService::class)->fillFromShopData(
236	                        $professional, $site, $brandProfile, $shopifyData['shop_data']
237	                    );
238	                }
239	
240	                app(ProfessionalCacheService::class)->invalidateProfessional($professional);
241	
242	                // Ensure the professional has a subscription – seed the free plan if none exists
243	                $this->siteProvisioning->ensureFreeSubscription($professional);
244	
245	                if ($createdProfessional) {
246	                    $this->createWelcomeNotification($professional);
247	                }
248	
249	                return [
250	                    'professional' => new ProfessionalDashboardResource($professional->fresh()),
251	                    'site' => $site->fresh(),
252	                    'shopify_integration_id' => $shopifyIntegrationId,
253	                ];
254	            });
255	        } catch (\Exception $e) {
256	            Log::error('Bootstrap transaction failed', [
257	                'error' => $e->getMessage(),
258	                'uid' => $uid,
259	            ]);
260	            throw $e;
261	        }
262	
263	        // Consume Shopify setup token AFTER transaction succeeds (prevents token loss on rollback)
264	        if (is_string($result['shopify_integration_id'] ?? null)) {
265	            $shopifySetupToken = trim((string) ($data['shopify_setup_token'] ?? ''));
266	            if ($shopifySetupToken !== '') {
267	                app(ShopifySetupTokenService::class)->consume($shopifySetupToken);
