328	    private function syncSiteBrandPartnerSettings(
329	        Site $site,
330	        BrandPartnerLinkService $brandPartnerLinks,
331	        string $affiliateProfessionalId
332	    ): void {
333	        $links = $brandPartnerLinks->getLinksForAffiliate($affiliateProfessionalId);
334	        $settings = is_array($site->settings) ? $site->settings : [];
335	
336	        $brandPartner = is_array($settings['brand_partner'] ?? null)
337	            ? $settings['brand_partner']
338	            : [];
339	
340	        $primaryLink = $links->firstWhere('slot', BrandPartnerLinkService::PRIMARY_SLOT);
341	        if ($primaryLink) {
342	            $brandPartner['professional_id'] = (string) $primaryLink->brand_professional_id;
343	        } else {
344	            unset($brandPartner['professional_id'], $brandPartner['professionalId']);
345	        }
346	
347	        $settings['brand_partner'] = $brandPartner;
348	        $settings['additional_brand_partners'] = $links
349	            ->filter(static fn ($link): bool => (int) $link->slot > BrandPartnerLinkService::PRIMARY_SLOT)
350	            ->sortBy('slot')
351	            ->map(static fn ($link): array => [
352	                'professional_id' => (string) $link->brand_professional_id,
353	            ])
354	            ->values()
355	            ->all();
356	
357	        $site->settings = $settings;
358	        $site->save();
359	    }
